if(op=="options-edit"&&request.ContainsKey("setting")&&(string)request["setting"]=="Extensions105"){string oldExt=(string)request["oldText"],newExt=(string)request["newText"];if(newExt!=".ca105"&&newExt!=".skip105"&&oldExt.TrimEnd(';')!=".ca105"&&oldExt.TrimEnd(';')!=".skip105")throw new InvalidOperationException("Only owned extension transaction");var extBoxes=Walk(window).OfType<TextBox>().Where(x=>x.IsVisible&&x.Text==oldExt&&x.TransformToAncestor(window).Transform(new Point()).X>245).ToArray();if(extBoxes.Length!=1)throw new InvalidOperationException("Ambiguous extension field");extBoxes[0].Text=newExt;extBoxes[0].GetBindingExpression(TextBox.TextProperty)?.UpdateSource();extBoxes[0].MoveFocus(new TraversalRequest(FocusNavigationDirection.Next));return new{status="observed",value=extBoxes[0].Text};}
